using Movers.Domain.CustomerLinks;
using Movers.Domain.Sales;
using Movers.Services.Common;
using Movers.Services.CustomerLinks;
using Movers.Services.Tenancy;

namespace Movers.Services.Sales;

public sealed class SalesService(ISalesRepository repository, ITenantContext tenantContext, Movers.Services.Numbering.IRecordNumbers numbers, ILeadInventoryRepository inventory, ICustomerReplyQueries replyQueries) : ISalesService
{
    public async Task<IReadOnlyList<LeadStatusModel>> ListLeadStatusesAsync(CancellationToken token) => (await repository.ListLeadStatusesAsync(token)).Select(Map).ToList();
    public async Task<LeadStatusModel> CreateLeadStatusAsync(SaveLeadStatusCommand c, CancellationToken t) { await EnsureLeadStatusCode(c.Code, null, t); var x = new LeadStatus(tenantContext.TenantId, c.Code, c.Name, c.DisplayOrder, c.Color, c.IsClosed); repository.AddLeadStatus(x); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<LeadStatusModel?> UpdateLeadStatusAsync(Guid id, SaveLeadStatusCommand c, CancellationToken t) { var x = await repository.GetLeadStatusAsync(id, true, t); if (x is null) return null; await EnsureLeadStatusCode(c.Code, id, t); x.Update(c.Code, c.Name, c.DisplayOrder, c.Color, c.IsClosed); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<LeadStatusModel?> SetLeadStatusActiveAsync(Guid id, bool active, CancellationToken t) { var x = await repository.GetLeadStatusAsync(id, true, t); if (x is null) return null; x.SetActive(active); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<IReadOnlyList<FollowUpStatusModel>> ListFollowUpStatusesAsync(CancellationToken token) => (await repository.ListFollowUpStatusesAsync(token)).Select(Map).ToList();
    public async Task<FollowUpStatusModel> CreateFollowUpStatusAsync(SaveFollowUpStatusCommand c, CancellationToken t) { await EnsureFollowStatusCode(c.Code, null, t); var x = new FollowUpStatus(tenantContext.TenantId, c.Code, c.Name, c.DisplayOrder, c.Color, c.IsCompleted); repository.AddFollowUpStatus(x); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<FollowUpStatusModel?> UpdateFollowUpStatusAsync(Guid id, SaveFollowUpStatusCommand c, CancellationToken t) { var x = await repository.GetFollowUpStatusAsync(id, true, t); if (x is null) return null; await EnsureFollowStatusCode(c.Code, id, t); x.Update(c.Code, c.Name, c.DisplayOrder, c.Color, c.IsCompleted); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<FollowUpStatusModel?> SetFollowUpStatusActiveAsync(Guid id, bool active, CancellationToken t) { var x = await repository.GetFollowUpStatusAsync(id, true, t); if (x is null) return null; x.SetActive(active); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<IReadOnlyList<MoveTypeModel>> ListMoveTypesAsync(CancellationToken t) => (await repository.ListMoveTypesAsync(t)).Select(Map).ToList();
    public async Task<MoveTypeModel> CreateMoveTypeAsync(SaveMoveTypeCommand c, CancellationToken t) { await EnsureMoveTypeCode(c.Code, null, t); var x = new MoveType(tenantContext.TenantId, c.Code, c.Name, c.DisplayOrder, c.Description); repository.AddMoveType(x); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<MoveTypeModel?> UpdateMoveTypeAsync(Guid id, SaveMoveTypeCommand c, CancellationToken t) { var x = await repository.GetMoveTypeAsync(id, true, t); if (x is null) return null; await EnsureMoveTypeCode(c.Code, id, t); x.Update(c.Code, c.Name, c.DisplayOrder, c.Description); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<MoveTypeModel?> SetMoveTypeActiveAsync(Guid id, bool active, CancellationToken t) { var x = await repository.GetMoveTypeAsync(id, true, t); if (x is null) return null; x.SetActive(active); await repository.SaveChangesAsync(t); return Map(x); }
    public async Task<IReadOnlyList<SalesLeadModel>> ListLeadsAsync(CancellationToken t) => await MapLeads(await repository.ListLeadsAsync(t), await inventory.Totals(t), t);
    public async Task<PagedResult<SalesLeadModel>> SearchLeadsAsync(SalesLeadListFilter filter, ListQuery query, CancellationToken t)
    {
        query = query.Normalized();
        var ids = string.IsNullOrWhiteSpace(filter.CustomerState) ? null : await replyQueries.RecordIdsInStateAsync(CustomerReplyRecordTypes.SalesLead, filter.CustomerState.Trim().ToUpperInvariant(), t);
        var (items, total) = await repository.SearchLeadsAsync(filter, query, ids, t);
        return new(await MapLeads(items, await inventory.Totals(items.Select(x => x.Id).ToList(), t), t), total);
    }
    public async Task<PagedResult<LeadStatusModel>> SearchLeadStatusesAsync(bool? active, ListQuery query, CancellationToken t) { var (items, total, summary) = await repository.SearchLeadStatusesAsync(active, query.Normalized(), t); return new(items.Select(Map).ToList(), total, summary); }
    public async Task<PagedResult<FollowUpStatusModel>> SearchFollowUpStatusesAsync(bool? active, ListQuery query, CancellationToken t) { var (items, total, summary) = await repository.SearchFollowUpStatusesAsync(active, query.Normalized(), t); return new(items.Select(Map).ToList(), total, summary); }
    public async Task<PagedResult<MoveTypeModel>> SearchMoveTypesAsync(bool? active, ListQuery query, CancellationToken t) { var (items, total, summary) = await repository.SearchMoveTypesAsync(active, query.Normalized(), t); return new(items.Select(Map).ToList(), total, summary); }
    private async Task<IReadOnlyList<SalesLeadModel>> MapLeads(IReadOnlyList<SalesLead> leads, IReadOnlyDictionary<Guid, LeadInventoryTotals> totals, CancellationToken t) { var statuses = (await repository.ListLeadStatusesAsync(t)).ToDictionary(x => x.Id); var moveTypes = (await repository.ListMoveTypesAsync(t)).ToDictionary(x => x.Id); var employees = (await repository.ListEmployeesAsync(t)).ToDictionary(x => x.Id, x => x.FullName); return leads.Select(x => Map(x, statuses[x.StatusId], moveTypes[x.MoveTypeId], x.AssignedEmployeeId.HasValue && employees.TryGetValue(x.AssignedEmployeeId.Value, out var name) ? name : null) with { ExpectedCbm = totals.GetValueOrDefault(x.Id)?.ExpectedCbm ?? 0, FragileItems = totals.GetValueOrDefault(x.Id)?.FragileItems ?? 0 }).ToList(); }
    public async Task<SalesLeadModel> CreateLeadAsync(SaveSalesLeadCommand c, CancellationToken t) { c = c with { LeadNumber = await numbers.Next("LD", t) }; await ValidateLead(null, c, t); var x = new SalesLead(tenantContext.TenantId, c.LeadNumber, c.CustomerName, c.Phone, c.Email, c.Source, c.MoveTypeId, c.Origin, c.Destination, c.ExpectedMoveDate, c.StatusId, c.AssignedEmployeeId, c.Notes); repository.AddLead(x); await repository.SaveChangesAsync(t); return (await ListLeadsAsync(t)).Single(y => y.Id == x.Id); }
    public async Task<SalesLeadModel?> UpdateLeadAsync(Guid id, SaveSalesLeadCommand c, CancellationToken t) { var x = await repository.GetLeadAsync(id, true, t); if (x is null) return null; c = c with { LeadNumber = x.LeadNumber }; await ValidateLead(id, c, t); x.Update(c.LeadNumber, c.CustomerName, c.Phone, c.Email, c.Source, c.MoveTypeId, c.Origin, c.Destination, c.ExpectedMoveDate, c.StatusId, c.AssignedEmployeeId, c.Notes); await repository.SaveChangesAsync(t); return (await ListLeadsAsync(t)).Single(y => y.Id == id); }
    public async Task<SalesLeadModel?> SetLeadActiveAsync(Guid id, bool active, CancellationToken t) { var x = await repository.GetLeadAsync(id, true, t); if (x is null) return null; x.SetActive(active); await repository.SaveChangesAsync(t); return (await ListLeadsAsync(t)).Single(y => y.Id == id); }
    public async Task<IReadOnlyList<FollowUpModel>> ListFollowUpsAsync(Guid leadId, CancellationToken t) { if (await repository.GetLeadAsync(leadId, false, t) is null) return []; var statuses = (await repository.ListFollowUpStatusesAsync(t)).ToDictionary(x => x.Id); return (await repository.ListFollowUpsAsync(leadId, t)).Select(x => Map(x, statuses[x.StatusId])).ToList(); }
    public async Task<FollowUpModel> CreateFollowUpAsync(Guid leadId, SaveFollowUpCommand c, CancellationToken t) { if (await repository.GetLeadAsync(leadId, false, t) is null) throw new InvalidOperationException("Sales lead was not found."); var status = await ValidFollowStatus(c.StatusId, t); var x = new LeadFollowUp(tenantContext.TenantId, leadId, c.ScheduledAtUtc, c.StatusId, c.Notes, c.NextFollowUpAtUtc); repository.AddFollowUp(x); await repository.SaveChangesAsync(t); return Map(x, status); }
    public async Task<FollowUpModel?> UpdateFollowUpAsync(Guid id, SaveFollowUpCommand c, CancellationToken t) { var x = await repository.GetFollowUpAsync(id, true, t); if (x is null) return null; var status = await ValidFollowStatus(c.StatusId, t); x.Update(c.ScheduledAtUtc, c.StatusId, c.Notes, c.NextFollowUpAtUtc); await repository.SaveChangesAsync(t); return Map(x, status); }
    private async Task ValidateLead(Guid? id, SaveSalesLeadCommand c, CancellationToken t) { if (await repository.LeadNumberExistsAsync(c.LeadNumber.Trim().ToUpperInvariant(), id, t)) throw new InvalidOperationException("This lead number is already in use."); var status = await repository.GetLeadStatusAsync(c.StatusId, false, t); if (status is null || !status.IsActive) throw new InvalidOperationException("Select an active lead status."); var moveType = await repository.GetMoveTypeAsync(c.MoveTypeId, false, t); if (moveType is null || !moveType.IsActive) throw new InvalidOperationException("Select an active move type."); if (c.AssignedEmployeeId.HasValue) { var employee = await repository.GetEmployeeAsync(c.AssignedEmployeeId.Value, t); if (employee is null || !employee.IsActive) throw new InvalidOperationException("Select an active employee."); } }
    private async Task<FollowUpStatus> ValidFollowStatus(Guid id, CancellationToken t) { var x = await repository.GetFollowUpStatusAsync(id, false, t); return x is null || !x.IsActive ? throw new InvalidOperationException("Select an active follow-up status.") : x; }
    private async Task EnsureLeadStatusCode(string code, Guid? id, CancellationToken t) { if (await repository.LeadStatusCodeExistsAsync(code.Trim().ToUpperInvariant(), id, t)) throw new InvalidOperationException("This lead status code is already in use."); }
    private async Task EnsureFollowStatusCode(string code, Guid? id, CancellationToken t) { if (await repository.FollowUpStatusCodeExistsAsync(code.Trim().ToUpperInvariant(), id, t)) throw new InvalidOperationException("This follow-up status code is already in use."); }
    private async Task EnsureMoveTypeCode(string code, Guid? id, CancellationToken t) { if (await repository.MoveTypeCodeExistsAsync(code.Trim().ToUpperInvariant(), id, t)) throw new InvalidOperationException("This move type code is already in use."); }
    private static LeadStatusModel Map(LeadStatus x) => new(x.SerialNo, x.Id, x.Code, x.Name, x.DisplayOrder, x.Color, x.IsClosed, x.IsActive);
    private static FollowUpStatusModel Map(FollowUpStatus x) => new(x.SerialNo, x.Id, x.Code, x.Name, x.DisplayOrder, x.Color, x.IsCompleted, x.IsActive);
    private static MoveTypeModel Map(MoveType x) => new(x.SerialNo, x.Id, x.Code, x.Name, x.DisplayOrder, x.Description, x.IsActive);
    private static SalesLeadModel Map(SalesLead x, LeadStatus s, MoveType m, string? employee) => new(x.SerialNo, x.Id, x.LeadNumber, x.CustomerName, x.Phone, x.Email, x.Source, x.MoveTypeId, m.Name, x.Origin, x.Destination, x.ExpectedMoveDate, x.StatusId, s.Name, s.Color, s.IsClosed, x.AssignedEmployeeId, employee, x.Notes, x.IsActive, x.CreatedAtUtc, x.UpdatedAtUtc);
    private static FollowUpModel Map(LeadFollowUp x, FollowUpStatus s) => new(x.SerialNo, x.Id, x.SalesLeadId, x.ScheduledAtUtc, x.StatusId, s.Name, s.Color, s.IsCompleted, x.Notes, x.NextFollowUpAtUtc, x.CreatedAtUtc, x.UpdatedAtUtc);
}
